#include <torch/extension.h>
#include <c10/core/DeviceGuard.h>
#include <c10/hip/HIPStream.h>
#include <c10/hip/HIPException.h>
#include <hip/hip_runtime.h>
__global__ void lm_pack_kernel(const c10::BFloat16* x,c10::BFloat16* y,int cols,bool reciprocal){
 __shared__ c10::BFloat16 tile[32][33];
 int bx=blockIdx.x,by=blockIdx.y;
 for(int p=threadIdx.x;p<1024;p+=256){int r=by*32+p/32,c=bx*32+p%32;if(r<36&&c<cols){float a=float(x[int64_t(r)*cols+c]);if(!isfinite(a))a=0.0f;a=fminf(fmaxf(a,-100.0f),100.0f);tile[p/32][p%32]=c10::BFloat16(reciprocal?a*0.01f:a/100.0f);}}
 __syncthreads();
 for(int p=threadIdx.x;p<1024;p+=256){int r=by*32+p%32,c=bx*32+p/32;if(r<36&&c<cols)y[int64_t(c)*36+r]=tile[p%32][p/32];}
}
torch::Tensor pack(torch::Tensor x,bool reciprocal){
 TORCH_CHECK(x.is_cuda()&&x.scalar_type()==at::kBFloat16&&x.is_contiguous()&&x.dim()==4&&x.size(0)==1&&x.size(1)==36&&x.size(2)==x.size(3));
 c10::DeviceGuard guard(x.device());int n=x.size(2),cols=n*n;auto y=torch::empty({1,n,n,36},x.options());
 hipLaunchKernelGGL(lm_pack_kernel,dim3((cols+31)/32,2),dim3(256),0,c10::hip::getCurrentHIPStream(),x.data_ptr<c10::BFloat16>(),y.data_ptr<c10::BFloat16>(),cols,reciprocal);C10_HIP_CHECK(hipGetLastError());return y;
}
PYBIND11_MODULE(TORCH_EXTENSION_NAME,m){m.def("pack",&pack);}

