import hashlib,json,pathlib,os,statistics
import torch
from torch.utils.cpp_extension import load
from benchmarks.atlasfold.profile_inference import resolve_physical_device,_GpuProcessMonitor
root=pathlib.Path('/media/IntelSSD/fireprot');src=pathlib.Path('/tmp/fireprot_atlas_lm_pack_probe.cu');build=root/'runtime/atlas_lm_pack_probe';build.mkdir(exist_ok=True)
torch.cuda.init();device=resolve_physical_device();monitor=_GpuProcessMonitor(device['gpu'],os.getpid(),1);monitor.start()
r={'device':device,'kernel_sha256':hashlib.sha256(src.read_bytes()).hexdigest(),'cases':[]}
def native(x):return x.nan_to_num_(nan=0,posinf=0,neginf=0).clamp_(-100,100).div_(100).moveaxis(1,-1).contiguous()
def timing(fn, x):
 for _ in range(2):fn(x.clone())
 vals=[]
 for _ in range(5):
  work=x.clone();a=torch.cuda.Event(enable_timing=True);b=torch.cuda.Event(enable_timing=True);a.record();fn(work);b.record();b.synchronize();vals.append(a.elapsed_time(b))
 return statistics.median(vals)
try:
 ext=load(name='atlas_lm_pack_probe',sources=[str(src)],build_directory=str(build),extra_cuda_cflags=['-O3'],verbose=False)
 with torch.inference_mode():
  for n in (1024,1026,1536,1538):
   torch.manual_seed(1203);bits=torch.randint(-32768,32768,(1,36,n,n),device='cuda',dtype=torch.int16);x=bits.view(torch.bfloat16);ref=native(x.clone())
   for reciprocal in (False,True):
    y=ext.pack(x,reciprocal);bad=int(torch.count_nonzero(y.view(torch.int16)!=ref.view(torch.int16)));r['cases'].append({'length':n,'reciprocal':reciprocal,'bit_mismatches':bad,'native_ms':timing(native,x),'candidate_ms':timing(lambda work:ext.pack(work,reciprocal),x)})
 r['status']='complete'
finally:
 r['isolation']=monitor.stop();(root/'outputs/atlasfold/lm-pack-probe.json').write_text(json.dumps(r,indent=2));print(json.dumps(r),flush=True)

