from benchmarks.atlasfold.profile_inference import resolve_physical_device,_GpuProcessMonitor
torch.cuda.init();device=resolve_physical_device();monitor=_GpuProcessMonitor(device['gpu'],os.getpid(),1);monitor.start();r={'device':device,'cases':[]}
state=torch.load('/media/PM982/engramfold/folding_e2e_20260921/weights/atlasfold/snapshot/weights/atlasfold-260703.pth',map_location='cpu',weights_only=True,mmap=True)
def native(x,w):
 a=x.nan_to_num_(nan=0,posinf=0,neginf=0).clamp_(-100,100).div_(100).moveaxis(1,-1)
 return torch.nn.functional.linear(a,w)
