 vals=[]
 for _ in range(5):
  work=x.clone();a=torch.cuda.Event(enable_timing=True);b=torch.cuda.Event(enable_timing=True);a.record();fn(work,w);b.record();b.synchronize();vals.append(a.elapsed_time(b))
