    row={'length':n,'layer':layer,'bit_mismatches':int(torch.count_nonzero(a.view(torch.int16)!=b.view(torch.int16))),'max_abs':float((a-b).abs().max()),'native_ms':timing(native,x,w),'candidate_ms':timing(candidate,x,w)};r['cases'].append(row)
 r['status']='complete'
