#include <torch/extension.h>
#include <c10/core/DeviceGuard.h>
#include <c10/hip/HIPStream.h>
#include <c10/hip/HIPException.h>
#include <hip/hip_runtime.h>
__global__ void lm_clean_kernel(c10::BFloat16* x,int64_t count){
 int64_t p=int64_t(blockIdx.x)*blockDim.x+threadIdx.x;
 if(p<count){float a=float(x[p]);if(!isfinite(a))a=0.0f;a=fminf(fmaxf(a,-100.0f),100.0f);x[p]=c10::BFloat16(a/100.0f);}
}
torch::Tensor clean(torch::Tensor x){
 TORCH_CHECK(x.is_cuda()&&x.scalar_type()==at::kBFloat16&&x.is_contiguous()&&x.dim()==4&&x.size(0)==1&&x.size(1)==36&&x.size(2)==x.size(3));
 c10::DeviceGuard guard(x.device());int64_t count=x.numel();
 hipLaunchKernelGGL(lm_clean_kernel,dim3((count+255)/256),dim3(256),0,c10::hip::getCurrentHIPStream(),x.data_ptr<c10::BFloat16>(),count);C10_HIP_CHECK(hipGetLastError());return x;
}
